`timescale 1ns / 1ps
// weapon_overlay: every pixel of the idle frame and of the firing frame
// (recoil + muzzle flash) against golden frames generated by
// scripts/gen_weapon_overlay.py straight from the sprite drawing; hidden when
// show=0. weapon_ctrl: flash/recoil lengths, one shot_fired per accepted
// shot, fire ignored during recoil and when not playing.
module tb_weapon;
    reg [6:0] px=0; reg [5:0] py=0;
    reg show=1, recoil=0, flash=0;
    reg [15:0] pixel_in=0;
    wire [15:0] pixel_out;
    weapon_overlay dut(.px(px),.py(py),.show(show),.recoil(recoil),.flash(flash),
        .pixel_in(pixel_in),.pixel_out(pixel_out));
    reg [15:0] golden [0:12287];
    reg clk=0; always #5 clk=~clk;
    reg rst=1, playing=0, fire=0;
    wire wflash, wrecoil, shot;
    weapon_ctrl #(.FLASH_SHIFT(4),.RECOIL_SHIFT(6)) ctrl(.clk(clk),.rst(rst),.playing(playing),
        .fire(fire),.flash(wflash),.recoil(wrecoil),.shot_fired(shot));
    integer f,x,y,failures=0,shots=0,flash_len=0,recoil_len=0,fd;
    always @(posedge clk) begin
        if(shot) shots=shots+1;
        if(wflash) flash_len=flash_len+1;
        if(wrecoil) recoil_len=recoil_len+1;
    end
    task fail;
        input [511:0] msg;
        begin failures=failures+1; $display("FAIL weapon: %0s",msg); end
    endtask
    task pulse_fire;
        begin @(negedge clk); fire=1; @(negedge clk); fire=0; end
    endtask
    initial begin
        // Golden frames: found next to the simulation, or in the source tree when
        // run by scripts/run_sim.py (build/sim_weapon) or a Vivado project.
        fd=$fopen("weapon_golden.hex","r");
        if(fd!=0) begin $fclose(fd); $readmemh("weapon_golden.hex", golden); end
        else begin
            fd=$fopen("../../sim/weapon_golden.hex","r");
            if(fd!=0) begin $fclose(fd); $readmemh("../../sim/weapon_golden.hex", golden); end
            else begin
                fd=$fopen("../../../../sim/weapon_golden.hex","r");
                if(fd!=0) begin $fclose(fd); $readmemh("../../../../sim/weapon_golden.hex", golden); end
                else begin $display("FAIL weapon: weapon_golden.hex not found (add it to the simulation sources)"); $finish; end
            end
        end
        for(f=0;f<2;f=f+1) begin
            recoil=f; flash=f;
            for(y=0;y<64;y=y+1) for(x=0;x<96;x=x+1) begin
                px=x; py=y; pixel_in=(x*7+y*13); #1;
                if(pixel_out!==golden[f*6144+y*96+x]) begin
                    failures=failures+1;
                    if(failures<6) $display("FAIL weapon: frame %0d (%0d,%0d) got %h expected %h",f,x,y,pixel_out,golden[f*6144+y*96+x]);
                end
            end
        end
        show=0; recoil=1; flash=1;
        for(y=0;y<64;y=y+1) for(x=0;x<96;x=x+1) begin
            px=x; py=y; pixel_in=(x*7+y*13); #1;
            if(pixel_out!==pixel_in) begin failures=failures+1; if(failures<6) $display("FAIL weapon: drawn while hidden"); end
        end
        // Preview of the idle and firing frames over the real sky/floor.
        fd=$fopen("weapon_preview.ppm","w"); $fwrite(fd,"P3\n192 64\n255\n");
        show=1;
        for(y=0;y<64;y=y+1) for(f=0;f<192;f=f+1) begin
            px=f%96; py=y; recoil=f/96; flash=f/96; pixel_in=(y<32) ? 16'h1084 : 16'h3166; #1;
            $fwrite(fd,"%0d %0d %0d\n",pixel_out[15:11]*255/31,pixel_out[10:5]*255/63,pixel_out[4:0]*255/31);
        end
        $fclose(fd);
        // ---- weapon_ctrl ----
        repeat(3) @(negedge clk); rst=0;
        pulse_fire; repeat(100) @(negedge clk);
        if(shots!=0 || flash_len!=0) fail("fired while not playing");
        playing=1;
        pulse_fire;
        repeat(20) @(negedge clk);
        pulse_fire;                                   // during recoil: ignored
        repeat(100) @(negedge clk);
        if(shots!=1) fail("shot during recoil was not ignored");
        if(flash_len<16 || flash_len>18) fail("flash length (must be one continuous 2^FLASH_SHIFT burst)");
        if(recoil_len<64 || recoil_len>66) fail("recoil length");
        pulse_fire; repeat(100) @(negedge clk);
        if(shots!=2) fail("second shot after recoil missing");
        if(failures==0) $display("PASS weapon: idle and firing frames match the sprite drawing pixel for pixel, hidden with the map, one continuous flash and recoil per shot, one shot_fired per shot, fire ignored during recoil and outside play");
        else $display("FAIL weapon total=%0d",failures);
        $finish;
    end
endmodule
